package com.particlelife.wallpaper;
import android.app.Activity;import android.app.WallpaperManager;import android.content.Intent;import android.os.Bundle;import android.content.SharedPreferences;import android.graphics.Color;import android.view.View;import android.widget.*;
public class SettingsActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);SharedPreferences pref=getSharedPreferences("settings",MODE_PRIVATE);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(36,42,36,24);layout.setBackgroundColor(Color.rgb(8,14,27));ScrollView scroll=new ScrollView(this);scroll.addView(layout);setContentView(scroll);
 TextView title=new TextView(this);title.setText("Particle Life — Bio-Atom (CHNOPS)");title.setTextSize(24);title.setTextColor(Color.WHITE);layout.addView(title);
 slider(layout,pref,"particles","Particles",180,600,420);slider(layout,pref,"bond","Bond probability",0,100,60);slider(layout,pref,"strength","Bond strength",10,100,55);slider(layout,pref,"noise","Random motion",0,100,25);slider(layout,pref,"fps","FPS (battery saver)",10,60,30);
 Button button=new Button(this);button.setText("Set Live Wallpaper");layout.addView(button);button.setOnClickListener(v->{Intent i=new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new android.content.ComponentName(this,BondWallpaperService.class));try{startActivity(i);}catch(Exception e){startActivity(new Intent(WallpaperManager.ACTION_LIVE_WALLPAPER_CHOOSER));}});
 TextView note=new TextView(this);note.setText("CHNOPS atoms: C, H, O, N, P, S. Simplified valence limits (4,1,2,3,3,2), approximate atomic masses and stochastic bonds. Educational visual model, not real molecular chemistry. Tap to add atoms. Pauses when hidden.");note.setTextColor(0xff94a3b8);layout.addView(note);
 }
 void slider(LinearLayout parent,SharedPreferences p,String key,String name,int min,int max,int def){TextView t=new TextView(this);t.setTextColor(Color.WHITE);t.setPadding(0,20,0,0);parent.addView(t);SeekBar bar=new SeekBar(this);bar.setMax(max-min);bar.setProgress(p.getInt(key,def)-min);parent.addView(bar);t.setText(name+": "+(bar.getProgress()+min));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int progress,boolean user){int value=progress+min;t.setText(name+": "+value);if(user)p.edit().putInt(key,value).apply();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});}
}
